package library.ui;
import library.model.*;import library.storage.*;import library.algorithms.*;import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.nio.file.*;import java.io.*;import java.util.HashMap;import java.util.Map;
public class LibraryFrame extends JFrame {
 private final Color navy=new Color(18,35,62),blue=new Color(47,102,190),bg=new Color(245,247,251);private final BookStore store=new BookStore(Paths.get("data/books.csv"));private Book[] books;private boolean storageReadFailed;private final CardLayout cards=new CardLayout();private final JPanel content=new JPanel(cards);private JTable table;private DefaultTableModel model;private JLabel status;private String buildingPage;private final Map<String,JLabel> pageStatuses=new HashMap<>();private final Map<String,JTable> pageTables=new HashMap<>();private final Map<String,DefaultTableModel> pageModels=new HashMap<>();
 public LibraryFrame(){setTitle("Atlas Library · Book Search System");setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(940,620));setSize(1180,760);setLocationRelativeTo(null);try{books=store.load();}catch(IOException ex){books=new Book[0];storageReadFailed=true;JOptionPane.showMessageDialog(this,"Could not load data/books.csv. Existing data is protected from overwrite.\n"+ex.getMessage(),"Data file error",JOptionPane.ERROR_MESSAGE);}getContentPane().setBackground(bg);setLayout(new BorderLayout());add(sidebar(),BorderLayout.WEST);add(content,BorderLayout.CENTER);for(String page:new String[]{"Overview","Books","Search","Algorithms","Library Ops","Analysis","About"})content.add(page(page),page);showPage("Overview");}
 private JPanel sidebar(){JPanel s=new JPanel();s.setBackground(navy);s.setPreferredSize(new Dimension(218,1));s.setLayout(new BoxLayout(s,BoxLayout.Y_AXIS));JLabel brand=new JLabel("  ◈  ATLAS LIBRARY");brand.setForeground(Color.WHITE);brand.setFont(new Font("Segoe UI",Font.BOLD,18));brand.setBorder(BorderFactory.createEmptyBorder(24,8,28,8));s.add(brand);for(String x:new String[]{"Overview","Books","Search","Algorithms","Library Ops","Analysis","About"}){JButton b=new JButton(x);b.setHorizontalAlignment(SwingConstants.LEFT);b.setForeground(new Color(224,232,245));b.setBackground(navy);b.setBorderPainted(false);b.setFocusPainted(false);b.setFont(new Font("Segoe UI",Font.PLAIN,14));b.setMaximumSize(new Dimension(210,44));b.setBorder(BorderFactory.createEmptyBorder(10,24,10,10));b.addActionListener(e->showPage(x));s.add(b);}s.add(Box.createVerticalGlue());JLabel foot=new JLabel("  DSA • Java Swing");foot.setForeground(new Color(150,170,200));foot.setBorder(BorderFactory.createEmptyBorder(20,8,20,8));s.add(foot);return s;}
 private void showPage(String p){cards.show(content,p);status=pageStatuses.get(p);table=pageTables.get(p);model=pageModels.get(p);refresh();}
 private JPanel page(String name){buildingPage=name;JPanel root=new JPanel(new BorderLayout(18,18));root.setBackground(bg);root.setBorder(BorderFactory.createEmptyBorder(24,28,24,28));JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JLabel title=new JLabel(name);title.setFont(new Font("Segoe UI",Font.BOLD,26));title.setForeground(navy);top.add(title,BorderLayout.WEST);JLabel pageStatus=new JLabel("Local data · autosaved");pageStatus.setForeground(new Color(90,105,125));pageStatuses.put(name,pageStatus);top.add(pageStatus,BorderLayout.EAST);root.add(top,BorderLayout.NORTH);JPanel body=new JPanel(new BorderLayout(14,14));body.setOpaque(false);switch(name){case "Overview":body.add(dashboard(),BorderLayout.NORTH);body.add(bookTable(),BorderLayout.CENTER);break;case "Books":body.add(bookControls(),BorderLayout.NORTH);body.add(bookTable(),BorderLayout.CENTER);break;case "Search":body.add(searchPanel(),BorderLayout.NORTH);body.add(bookTable(),BorderLayout.CENTER);break;case "Algorithms":body.add(sortPanel(),BorderLayout.NORTH);body.add(bookTable(),BorderLayout.CENTER);break;case "Library Ops":body.add(opsPanel(),BorderLayout.NORTH);body.add(bookTable(),BorderLayout.CENTER);break;case "Analysis":body.add(analysis(),BorderLayout.NORTH);break;default:body.add(about(),BorderLayout.NORTH);}root.add(body,BorderLayout.CENTER);return root;}
 private JPanel dashboard(){JPanel p=new JPanel(new GridLayout(1,4,12,12));p.setOpaque(false);String[] labels={"Total Books","Available","Issued","Categories"};for(String x:labels){JPanel c=card();JLabel l=new JLabel(x);l.setForeground(Color.GRAY);JLabel n=new JLabel("0");n.setName(x);n.setFont(new Font("Segoe UI",Font.BOLD,26));n.setForeground(navy);c.add(l);c.add(Box.createVerticalStrut(10));c.add(n);p.add(c);}return p;}
 private JPanel card(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(230,234,240)),BorderFactory.createEmptyBorder(16,18,16,18)));return p;}
 private JScrollPane bookTable(){String[] cols={"Book ID","Title","Author","Category","Year","Status"};model=new DefaultTableModel(cols,0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);pageModels.put(buildingPage,model);pageTables.put(buildingPage,table);table.setRowHeight(34);table.setFont(new Font("Segoe UI",Font.PLAIN,13));table.getTableHeader().setFont(new Font("Segoe UI",Font.BOLD,12));table.getTableHeader().setBackground(new Color(234,239,247));table.setSelectionBackground(new Color(218,231,251));JScrollPane sp=new JScrollPane(table);sp.setBorder(BorderFactory.createLineBorder(new Color(225,230,238)));return sp;}
 private JPanel bookControls(){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,8,8));p.setBackground(Color.WHITE);JButton add=button("＋ Add book"),edit=button("Edit selected"),del=button("Delete selected");add.addActionListener(e->editBook(null));edit.addActionListener(e->{Book b=selected();if(b!=null)editBook(b);});del.addActionListener(e->delete());p.add(add);p.add(edit);p.add(del);return p;}
 private JPanel searchPanel(){JPanel outer=new JPanel(new BorderLayout(8,8));outer.setOpaque(false);JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));p.setBackground(Color.WHITE);JComboBox<String> key=new JComboBox<>(new String[]{"Book ID","Title","Author"}),algo=new JComboBox<>(new String[]{"Linear Search","Binary Search"});JTextField term=new JTextField(18);JButton go=button("Start search"),clear=button("Reset");TracePlayer player=new TracePlayer("Search");go.addActionListener(e->{if(term.getText().trim().isEmpty()){message("Enter a search value",true);return;}String q=term.getText().trim(),k=(String)key.getSelectedItem();boolean binary=algo.getSelectedIndex()==1;player.build(()->Algorithms.searchTrace(books,q,k,binary),false);});clear.addActionListener(e->{player.reset();term.setText("");refresh();});p.add(key);p.add(term);p.add(algo);p.add(go);p.add(clear);outer.add(p,BorderLayout.NORTH);outer.add(player,BorderLayout.CENTER);return outer;}
 private JPanel sortPanel(){JPanel outer=new JPanel(new BorderLayout(8,8));outer.setOpaque(false);JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));p.setBackground(Color.WHITE);JComboBox<String> key=new JComboBox<>(new String[]{"Book ID","Title","Author","Publication Year"}),algo=new JComboBox<>(new String[]{"Bubble Sort","Selection Sort","Insertion Sort"});JButton run=button("Start sort");TracePlayer player=new TracePlayer("Algorithms");run.addActionListener(e->{String k=(String)key.getSelectedItem(),a=(String)algo.getSelectedItem();player.build(()->Algorithms.sortTrace(books,k,a),true);});p.add(algo);p.add(key);p.add(run);outer.add(p,BorderLayout.NORTH);outer.add(player,BorderLayout.CENTER);return outer;}
 private final class TracePlayer extends JPanel {
  final String ownerPage;
  final TraceCanvas canvas=new TraceCanvas(); final JLabel stepLabel=new JLabel("Ready · choose an algorithm to begin"),stats=new JLabel("Comparisons 0   ·   Swaps / shifts 0");
  final JSlider speed=new JSlider(100,1000,500);final Timer timer;Algorithms.Trace trace;int index;SwingWorker<Algorithms.Trace,Void> worker;
  TracePlayer(String ownerPage){super(new BorderLayout(8,8));this.ownerPage=ownerPage;setOpaque(false);canvas.setPreferredSize(new Dimension(500,210));JPanel card=new JPanel(new BorderLayout(8,8));card.setBackground(Color.WHITE);card.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(225,230,238)),BorderFactory.createEmptyBorder(10,12,10,12)));card.add(canvas,BorderLayout.CENTER);JPanel lower=new JPanel(new BorderLayout(8,4));lower.setOpaque(false);lower.add(stepLabel,BorderLayout.NORTH);lower.add(stats,BorderLayout.CENTER);JPanel ctrls=new JPanel(new FlowLayout(FlowLayout.LEFT,6,2));ctrls.setOpaque(false);JButton start=button("Start"),pause=button("Pause"),resume=button("Resume"),reset=button("Reset");ctrls.add(start);ctrls.add(pause);ctrls.add(resume);ctrls.add(reset);ctrls.add(new JLabel("Slow / Fast"));speed.setPreferredSize(new Dimension(110,26));ctrls.add(speed);lower.add(ctrls,BorderLayout.SOUTH);card.add(lower,BorderLayout.SOUTH);add(card);timer=new Timer(1100-speed.getValue(),e->advance());speed.addChangeListener(e->timer.setDelay(1100-speed.getValue()));start.addActionListener(e->{if(trace!=null){index=0;showStep();timer.start();}});pause.addActionListener(e->timer.stop());resume.addActionListener(e->{if(trace!=null&&index<trace.steps.size())timer.start();});reset.addActionListener(e->reset());}
  void build(java.util.function.Supplier<Algorithms.Trace> supplier,boolean sort){timer.stop();if(worker!=null)worker.cancel(true);trace=null;stepLabel.setText("Preparing actual algorithm trace…");worker=new SwingWorker<Algorithms.Trace,Void>(){protected Algorithms.Trace doInBackground(){return supplier.get();}protected void done(){if(isCancelled())return;try{play(get(),sort);}catch(Exception ex){stepLabel.setText("Could not prepare visualization: "+ex.getMessage());}}};worker.execute();}
  void play(Algorithms.Trace t,boolean sort){timer.stop();trace=t;index=0;canvas.sortMode=sort;showStep();timer.start();}
  void advance(){if(trace==null)return;if(index+1<trace.steps.size()){index++;showStep();}else{timer.stop();Algorithms.Result r=trace.result;DefaultTableModel target=pageModels.get(ownerPage);target.setRowCount(0);for(Book b:r.books)addRow(target,b);stats.setText("Completed · "+r.comparisons+" comparisons · "+r.moves+" swaps / shifts · "+r.nanos+" ns");}}
  void showStep(){Algorithms.Step s=trace.steps.get(index);canvas.step=s;canvas.repaint();stepLabel.setText("Step "+(index+1)+" / "+trace.steps.size()+" · "+s.description);stats.setText("Comparisons "+s.comparisons+"   ·   Swaps / shifts "+s.moves);}
  void reset(){timer.stop();if(worker!=null)worker.cancel(true);trace=null;index=0;canvas.step=null;canvas.repaint();stepLabel.setText("Ready · choose an algorithm to begin");stats.setText("Comparisons 0   ·   Swaps / shifts 0");}
 }
 private final class TraceCanvas extends JPanel {Algorithms.Step step;boolean sortMode;TraceCanvas(){setBackground(Color.WHITE);setOpaque(true);}protected void paintComponent(Graphics g){super.paintComponent(g);if(step==null)return;Book[] a=step.state;if(a.length==0){g.setColor(new Color(100,110,125));g.drawString("No books to visualize",18,35);return;}int left=18,base=getHeight()-35,usable=Math.max(20,getWidth()-36),gap=8,w=Math.max(12,(usable-gap*(a.length-1))/a.length),max=1;for(Book b:a)max=Math.max(max,b.year);for(int i=0;i<a.length;i++){int h=24+(int)((double)a[i].year/max*(getHeight()-82));int x=left+i*(w+gap),y=base-h;Color color=new Color(174,192,218);if(i==step.found)color=new Color(38,158,111);else if(i==step.first||i==step.second||i==step.mid)color=new Color(233,155,59);else if(!sortMode&&step.low>=0&&i>=step.low&&i<=step.high)color=new Color(87,143,218);g.setColor(color);g.fillRoundRect(x,y,w,h,8,8);g.setColor(navy);g.setFont(new Font("Segoe UI",Font.BOLD,Math.min(12,w)));String label=a[i].id;g.drawString(label,x,y-5);g.setColor(Color.DARK_GRAY);g.setFont(new Font("Segoe UI",Font.PLAIN,10));g.drawString(String.valueOf(i),x,base+16);}}}
 private JPanel opsPanel(){JPanel p=new JPanel(new FlowLayout(FlowLayout.LEFT,10,10));p.setBackground(Color.WHITE);JButton issue=button("Issue selected"),ret=button("Return selected"),avail=button("Available books"),issued=button("Issued books");issue.addActionListener(e->availability(true));ret.addActionListener(e->availability(false));avail.addActionListener(e->filter(true));issued.addActionListener(e->filter(false));p.add(issue);p.add(ret);p.add(avail);p.add(issued);return p;}
 private JPanel analysis(){JTextArea t=new JTextArea("SEARCHING\nLinear Search: Best O(1) · Average O(n) · Worst O(n)\nBinary Search: Best O(1) · Average/Worst O(log n); sorted key required.\n\nSORTING\nBubble Sort: Best O(n) with early exit · Average/Worst O(n²)\nSelection Sort: Best/Average/Worst O(n²)\nInsertion Sort: Best O(n) · Average/Worst O(n²)\n\nExecution time is measured with System.nanoTime around the in-memory algorithm; it is indicative and varies with JVM warmup and machine load.");t.setEditable(false);t.setFont(new Font("Segoe UI",Font.PLAIN,16));t.setBorder(BorderFactory.createEmptyBorder(20,20,20,20));JPanel p=new JPanel(new BorderLayout());p.add(t);return p;}
 private JPanel about(){JPanel p=card();JLabel l=new JLabel("Atlas Library · Array-based search and sorting demonstration");l.setFont(new Font("Segoe UI",Font.PLAIN,18));p.add(l);return p;}
 private JButton button(String s){JButton b=new JButton(s);b.setBackground(blue);b.setForeground(Color.WHITE);b.setFocusPainted(false);b.setBorder(BorderFactory.createEmptyBorder(9,15,9,15));return b;}
 private Book selected(){int i=table.getSelectedRow();if(i<0){message("Select a book first",true);return null;}String id=String.valueOf(model.getValueAt(i,0));for(Book b:books)if(b.id.equals(id))return b;message("Selected record is no longer available",true);return null;}
 private void editBook(Book old){JTextField[] f={new JTextField(old==null?"":old.id),new JTextField(old==null?"":old.title),new JTextField(old==null?"":old.author),new JTextField(old==null?"":old.category),new JTextField(old==null?"":String.valueOf(old.year))};String[] labels={"Book ID","Title","Author","Category","Publication year"};JPanel panel=new JPanel(new GridLayout(5,2,8,8));for(int i=0;i<5;i++){panel.add(new JLabel(labels[i]));panel.add(f[i]);}if(JOptionPane.showConfirmDialog(this,panel,old==null?"Add book":"Edit book",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{String id=f[0].getText().trim();if(id.isEmpty()||f[1].getText().isBlank()||f[2].getText().isBlank())throw new IllegalArgumentException("ID, title and author are required.");int year=Integer.parseInt(f[4].getText().trim());if(year<0||year>2100)throw new IllegalArgumentException("Enter a valid publication year.");if(old==null){for(Book b:books)if(b.id.equalsIgnoreCase(id))throw new IllegalArgumentException("Book ID already exists.");Book[] n=java.util.Arrays.copyOf(books,books.length+1);n[books.length]=new Book(id,f[1].getText().trim(),f[2].getText().trim(),f[3].getText().trim(),year,true);books=n;}else{for(Book b:books)if(b!=old&&b.id.equalsIgnoreCase(id))throw new IllegalArgumentException("Book ID already exists.");old.id=id;old.title=f[1].getText().trim();old.author=f[2].getText().trim();old.category=f[3].getText().trim();old.year=year;}persist();refresh();}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Check book details",JOptionPane.ERROR_MESSAGE);}}
 private void delete(){Book b=selected();if(b==null)return;if(JOptionPane.showConfirmDialog(this,"Delete ‘"+b.title+"’?","Confirm deletion",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;Book[] n=new Book[books.length-1];for(int i=0,k=0;i<books.length;i++)if(books[i]!=b)n[k++]=books[i];books=n;persist();refresh();}
 private void availability(boolean issue){Book b=selected();if(b==null)return;if(issue&&!b.available||!issue&&b.available){message(issue?"This book is already issued":"This book is not currently issued",true);return;}b.available=!issue;persist();refresh();}
 private void filter(boolean available){model.setRowCount(0);for(Book b:books)if(b.available==available)addRow(b);}
 private void persist(){if(storageReadFailed){message("Save blocked: resolve the data file error to protect existing records",true);return;}try{store.save(books);message("Saved to data/books.csv",false);}catch(IOException e){message("Could not save: "+e.getMessage(),true);}}
 private void refresh(){for(DefaultTableModel pageModel:pageModels.values()){pageModel.setRowCount(0);for(Book b:books)addRow(pageModel,b);}for(Component c:content.getComponents())if(c.isVisible())walk(c);}
 private void walk(Component c){if(c instanceof JLabel&&((JLabel)c).getName()!=null){String n=((JLabel)c).getName();int val=0;if(n.equals("Total Books"))val=books.length;else if(n.equals("Available")){for(Book b:books)if(b.available)val++;}else if(n.equals("Issued")){for(Book b:books)if(!b.available)val++;}else{java.util.HashSet<String>s=new java.util.HashSet<>();for(Book b:books)s.add(b.category);val=s.size();}((JLabel)c).setText(String.valueOf(val));}if(c instanceof Container)for(Component x:((Container)c).getComponents())walk(x);}
 private void addRow(Book b){addRow(model,b);}private void addRow(DefaultTableModel target,Book b){target.addRow(new Object[]{b.id,b.title,b.author,b.category,b.year,b.available?"Available":"Issued"});}private void message(String s,boolean err){if(status!=null){status.setText(s);status.setForeground(err?new Color(180,55,55):new Color(35,130,90));}}
}

